  const { data: serviceProcess } = useSiteContent<ProcessStep[]>("service_process", serviceProcessMock);
  const totalSteps = serviceProcess.length;

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  const goToStep = useCallback(
    (index: number) => {
      if (index === activeStep) return;
      setDirection(index > activeStep ? "right" : "left");
      setActiveStep(index);
    },
    [activeStep]
  );

  const goToPrev = useCallback(() => {
    if (activeStep > 0) {
      setDirection("left");
      setActiveStep((prev) => prev - 1);
    }
  }, [activeStep]);

  const goToNext = useCallback(() => {
    if (activeStep < totalSteps - 1) {
      setDirection("right");
      setActiveStep((prev) => prev + 1);
    } else {
      // Loop back to first step
      setDirection("right");
      setActiveStep(0);
    }
  }, [activeStep, totalSteps]);

  // Auto-play
  useEffect(() => {
    if (!isVisible || isPaused) return;

    autoPlayTimer.current = setInterval(() => {
      setDirection("right");
      setActiveStep((prev) => (prev < totalSteps - 1 ? prev + 1 : 0));
    }, AUTO_PLAY_INTERVAL);

    return () => {
      if (autoPlayTimer.current) clearInterval(autoPlayTimer.current);
    };
  }, [isVisible, isPaused, totalSteps]);

  // Measure active card height for dynamic container sizing
