// ── Site settings sync ──
const SITE_SETTINGS_KEY = "admin_site_settings";
const SITE_SETTINGS_SUPABASE_KEY = "site_settings";

async function syncSiteSettings(): Promise<void> {
  try {
    const { data: row } = await supabase
      .from("site_content")
      .select("content")
      .eq("key", SITE_SETTINGS_SUPABASE_KEY)
      .maybeSingle();

    if (row?.content) {
      const payload = JSON.stringify(row.content);
      if (localStorage.getItem(SITE_SETTINGS_KEY) !== payload) {
        localStorage.setItem(SITE_SETTINGS_KEY, payload);
        window.dispatchEvent(new StorageEvent("storage", { key: SITE_SETTINGS_KEY, newValue: payload }));
      }
    }
  } catch { /* ignore */ }
}

