// ---- Cached data (for synchronous frontend usage) ----
let cachedResponses: Record<string, AIResponse> | null = null;
let cachedRules: AIRule[] | null = null;

// ---- Responses (admin: Supabase direct; frontend: cached with sync) ----

export function loadResponses(): Record<string, AIResponse> {
  if (cachedResponses) return { ...cachedResponses };
  try {
    const raw = localStorage.getItem(STORAGE_RESPONSES);
    if (raw) {
      const overrides = JSON.parse(raw) as Record<string, AIResponse>;
      return { ...defaultResponses, ...overrides };
    }
  } catch { /* ignore */ }
  return { ...defaultResponses };
}

export function saveResponses(responses: Record<string, AIResponse>): void {
  const diff: Record<string, AIResponse> = {};
  for (const [key, value] of Object.entries(responses)) {
    const original = defaultResponses[key];
    if (!original || JSON.stringify(original) !== JSON.stringify(value)) {
      diff[key] = value;
    }
  }
  localStorage.setItem(STORAGE_RESPONSES, JSON.stringify(diff));
  cachedResponses = responses;
}

export function getResponse(id: string): AIResponse | undefined {
  return loadResponses()[id];
}

export function deleteResponse(id: string): void {
  const all = { ...loadResponses() };
  delete all[id];
  saveResponses(all);
  cachedResponses = all;
}

export function resetResponse(id: string): void {
  const overrides = loadOverrides(STORAGE_RESPONSES);
  delete overrides[id];
  localStorage.setItem(STORAGE_RESPONSES, JSON.stringify(overrides));
  cachedResponses = null;
}

