export interface RolePermissions {
  role: string;
  description: string;
  isSystem: boolean;
  permissions: Record<string, boolean>;
}

const allPermissionKeys = permissionModules.flatMap((mod) => mod.children.map((c) => c.key));

function allOff(): Record<string, boolean> {
  return Object.fromEntries(allPermissionKeys.map((k) => [k, false]));
}

