  const { hasGranularPermission } = usePermissions();
  const [navType, setNavType] = useState<NavType>("frontend");
  const [frontendItems, setFrontendItems] = useState<NavItem[]>(() => loadNav("frontend"));
  const [backendItems, setBackendItems] = useState<NavItem[]>(() => loadNav("backend"));
  const [footerItems, setFooterItems] = useState<NavItem[]>(() => loadNav("footer"));
  const [showModal, setShowModal] = useState(false);
