function hasAnyPerm(rp: RolePermissions, perms: string[], isSuperAdmin: boolean): boolean {
  if (isSuperAdmin) return true;
  return perms.some((p) => rp.permissions[p]);
}

function hasPerm(rp: RolePermissions, perm: string, isSuperAdmin: boolean): boolean {
  if (isSuperAdmin) return true;
  return !!rp.permissions[perm];
}

function getDataScopeLabel(rp: RolePermissions, scope: NavItem["dataScope"], isSuperAdmin: boolean): string | null {
  if (!scope) return null;
  if (isSuperAdmin) return scope.allLabel;
  if (rp.permissions[scope.all]) return scope.allLabel;
  if (rp.permissions[scope.own]) return scope.ownLabel;
  return null;
}

interface PermissionPreviewProps {
  rolePerms: RolePermissions;
  allRolePermissions: RolePermissions[];
}

