  // ── Folder-level stats ──
  const folderStats = useMemo(() => {
    const map = new Map<string, { total: number; success: number; failed: number }>();
    for (const r of ctx.downloadHistory) {
      const f = r.folder || "__uncategorized__";
      const entry = map.get(f) || { total: 0, success: 0, failed: 0 };
      entry.total++;
      if (r.success) entry.success++;
      else entry.failed++;
      map.set(f, entry);
    }
    return Array.from(map.entries())
      .map(([folder, stats]) => ({
        folder,
        label: folder === "__uncategorized__" ? "未分类" : (ctx.dynamicFolderList.find((f) => f.key === folder)?.label || folder),
        ...stats,
        rate: Math.round((stats.success / stats.total) * 100),
      }))
      .sort((a, b) => b.total - a.total);
  }, [ctx.downloadHistory, ctx.dynamicFolderList]);

  // ── Filtered records ──
  const filteredRecords = useMemo(() => {
    let records = ctx.downloadHistory;
    if (folderFilter) {
      records = records.filter((r) => {
        const f = r.folder || "__uncategorized__";
        return f === folderFilter;
      });
    }
    if (failuresOnly) {
      records = records.filter((r) => !r.success);
    }
    return records;
  }, [ctx.downloadHistory, folderFilter, failuresOnly]);

  if (!ctx.showDownloadHistory) return null;

  const selectedFolderStats = folderFilter
    ? folderStats.find((f) => f.folder === folderFilter)
    : null;

