                  <div className="flex items-center gap-1.5"><span className="text-xs text-foreground-400">每页</span><select value={pageSize} onChange={(e) => { setPageSize(Number(e.target.value)); setCurrentPage(1); }} className="rounded-md border border-background-200 bg-background-50 px-2 py-1 text-xs text-foreground-700 focus:outline-none focus:ring-1 focus:ring-primary-400 cursor-pointer">{PAGE_SIZE_OPTIONS.map((n) => (<option key={n} value={n}>{n} 条</option>))}</select></div>
