import { createPortal } from "react-dom";
import { Button } from "@/components/base/Button";
import { Input } from "@/components/base/Input";
import type { SlotState, BatchReportItem } from "./types";
import { supabase } from "@/lib/supabase";

/* ── Regex History ── */

interface RegexHistoryEntry {
  id: string;
  scope: "manualUrl" | "currentUrl";
  pattern: string;
  replacement: string;
  created_at: string;
}

export type { RegexHistoryEntry };

export async function loadRegexHistory(): Promise<RegexHistoryEntry[]> {
  const { data, error } = await supabase
    .from("regex_history")
    .select("*")
    .order("created_at", { ascending: false })
    .limit(50);

  if (error) {
    console.warn("[regex_history] load failed:", error.message);
    return [];
  }
  return data as RegexHistoryEntry[];
}

export async function addRegexHistoryEntry(entry: Omit<RegexHistoryEntry, "id" | "created_at">) {
  // Check for duplicates first
  const { data: existing } = await supabase
    .from("regex_history")
    .select("id")
    .eq("scope", entry.scope)
    .eq("pattern", entry.pattern)
    .eq("replacement", entry.replacement)
    .limit(1);

  if (existing && existing.length > 0) return; // already exists, skip

  const { error } = await supabase
    .from("regex_history")
    .insert(entry);

  if (error) console.warn("[regex_history] insert failed:", error.message);

  // Prune to keep only latest 50
  const { data: all } = await supabase
    .from("regex_history")
    .select("id")
    .order("created_at", { ascending: false });

  if (all && all.length > 50) {
    const idsToDelete = all.slice(50).map((r) => r.id);
    await supabase.from("regex_history").delete().in("id", idsToDelete);
  }
}

export async function deleteRegexHistoryEntry(id: string) {
  const { error } = await supabase
    .from("regex_history")
    .delete()
    .eq("id", id);

  if (error) console.warn("[regex_history] delete failed:", error.message);
}

export async function clearRegexHistory() {
  const { error } = await supabase
    .from("regex_history")
    .delete()
    .neq("id", "00000000-0000-0000-0000-000000000000");

  if (error) console.warn("[regex_history] clear failed:", error.message);
}

