        // Query Supabase for extra mappings (is_active records not in hardcoded or pending)
        const allKnownKeys = new Set([...hardcodedKeys, ...pendingKeys]);
        const { data: siteImagesData } = await supabase
          .from("site_images")
          .select("image_key")
          .eq("is_active", true);

        const orphanKeys: string[] = [];
