    try {
      const { data, error } = await supabase
        .from("events")
        .select("*")
        .eq("slug", slug)
        .eq("status", "active")
        .maybeSingle();

      if (error) throw error;
      if (data) {
        setEvent(data as EventItem);
      } else {
        const mock = mockEvents.find((e) => e.slug === slug && e.status === "active");
        if (mock) {
          setEvent(mock as unknown as EventItem);
        } else {
          setNotFound(true);
        }
      }
    } catch {
      const mock = mockEvents.find((e) => e.slug === slug && e.status === "active");
      if (mock) {
        setEvent(mock as unknown as EventItem);
      } else {
        setNotFound(true);
      }
    } finally {
      setLoading(false);
    }
