/* ── Lazy page imports ──
   All non-home pages are code-split so the landing page stays light.
   Admin bundle is completely separate — no recharts/firebase leak into public pages. */

const ContactPage = lazy(() => import("../pages/contact/page"));
const AboutPage = lazy(() => import("../pages/about/page"));
const CasesPage = lazy(() => import("../pages/cases/page"));
const LegalPage = lazy(() => import("../pages/legal/page"));
const ResourcesDownloadsPage = lazy(() => import("../pages/resources/downloads/page"));
const ResourcesFAQPage = lazy(() => import("../pages/resources/faq/page"));
const OpsServicePage = lazy(() => import("../pages/services/ops/page"));
const ServiceDetailPage = lazy(() => import("../pages/services/detail/page"));
const ProductsPage = lazy(() => import("../pages/products/page"));
const ProductDetailPage = lazy(() => import("../pages/products/detail/page"));
const EventsPage = lazy(() => import("../pages/events/page"));
const EventDetailPage = lazy(() => import("../pages/events/detail/page"));

// ── Account pages ──
const AccountLoginPage = lazy(() => import("../pages/account/login/page"));
const AccountRegisterPage = lazy(() => import("../pages/account/register/page"));
const AccountPage = lazy(() => import("../pages/account/page"));

/* Admin pages — fully separate chunk */
const AdminLoginPage = lazy(() => import("../pages/admin/login/page"));
const AdminSetPasswordPage = lazy(() => import("../pages/admin/set-password/page"));
const AdminDashboard = lazy(() => import("../pages/admin/dashboard/page"));
const AdminServicesPage = lazy(() => import("../pages/admin/services/page"));
const AdminCasesPage = lazy(() => import("../pages/admin/cases/page"));
