const AdminSettingsPage = lazy(() => import("../pages/admin/settings/page"));
const AdminNotificationsPage = lazy(() => import("../pages/admin/notifications/page"));
const AdminTeamPage = lazy(() => import("../pages/admin/team/page"));
const AdminSiteSettingsPage = lazy(() => import("../pages/admin/site/settings/page"));
const AdminSiteUsersPage = lazy(() => import("../pages/admin/site/users/page"));
const AdminSitePermissionsPage = lazy(() => import("../pages/admin/site/permissions/page"));
const AdminSiteNavigationPage = lazy(() => import("../pages/admin/site/navigation/page"));
const AIAssistantAdminPage = lazy(() => import("../pages/admin/ai-assistant/page"));
const AdminDownloadsPage = lazy(() => import("../pages/admin/resources/downloads/page"));
