const AdminAssetsPage = lazy(() => import("../pages/admin/resources/assets/page"));
const AdminContentPage = lazy(() => import("../pages/admin/content/page"));
const AdminSystemLogsPage = lazy(() => import("../pages/admin/system/logs/page"));
const AdminEventsPage = lazy(() => import("../pages/admin/events/page"));
const AdminProductsPage = lazy(() => import("../pages/admin/products/page"));

/* ── Shared Suspense fallback ── */
function LazyFallback() {
  return (
    <div className="flex items-center justify-center min-h-screen bg-background-50">
      <div className="flex flex-col items-center gap-3">
        <div className="w-8 h-8 border-2 border-primary-500 border-t-transparent rounded-full animate-spin" />
        <span className="text-sm text-foreground-500">加载中...</span>
      </div>
    </div>
  );
}

function Lazy({ children }: { children: React.ReactNode }) {
  return <Suspense fallback={<LazyFallback />}>{children}</Suspense>;
}

/* ── Permission-wrapped lazy page helper ── */
function ProtectedPage({
  children,
  permission,
  anyPermission,
}: {
  children: React.ReactNode;
  permission?: string;
  anyPermission?: string[];
}) {
  if (permission || anyPermission) {
    return (
      <Lazy>
        <PermissionGuard permission={permission} anyPermission={anyPermission}>
          {children}
        </PermissionGuard>
      </Lazy>
    );
  }
  return <Lazy>{children}</Lazy>;
}

